import hashlib, subprocess, shutil, os
LEAN = 'def gate (n : Nat) (p q : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g < h → g < n ∨ (p g ∧ (q g ∨ ¬ ∀ j, j < g → q j))\ndef blend (S : Nat → Prop) (a b : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ a h) ∨ (¬ S h ∧ b h)\ndef eventual (p : Nat → Prop) : Prop := ∃ H, ∀ h, H ≤ h → p h\ndef dbtrace (n k : Nat) (S : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ h < k) ∨ (¬ S h ∧ h ≤ n)\ndef selfeq (n k : Nat) (S d x : Nat → Prop) : Prop :=\n  ∀ h, x h ↔ blend S (fun h => ∀ g, g + k ≤ h → x g) (gate n x d) h\n\ntheorem first_hole (d : Nat → Prop) (t : Nat)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t) (g : Nat) :\n    (d g ∨ ¬ ∀ j, j < g → d j) ↔ g ≠ t := by\n  classical\n  constructor\n  · intro H e\n    subst g\n    rcases H with hd | hd\n    · exact hole hd\n    · exact hd pre\n  · intro H\n    by_cases hg : g < t\n    · exact Or.inl (pre g hg)\n    · exact Or.inr (fun hh => hole (hh t (by omega)))\n\ntheorem least_failure (d : Nat → Prop) (b : Nat) (hb : ¬ d b) :\n    ∃ t, t ≤ b ∧ ¬ d t ∧ ∀ j, j < t → d j := by\n  classical\n  induction b using Nat.strongRecOn with\n  | ind b ih =>\n    by_cases H : ∀ j, j < b → d j\n    · exact ⟨b, Nat.le_refl b, hb, H⟩\n    · obtain ⟨j, hj⟩ := Classical.not_forall.mp H\n      have hjb : j < b := Classical.byContradiction (fun hh => hj (fun h => False.elim (hh h)))\n      have hjd : ¬ d j := fun hd => hj (fun _ => hd)\n      obtain ⟨t, ht, hdt, hp⟩ := ih j hjb hjd\n      exact ⟨t, by omega, hdt, hp⟩\n\ntheorem graded_self_law (n k t : Nat) (hk : 1 ≤ k) (S d x : Nat → Prop)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t)\n    (eqn : selfeq n k S d x) :\n    eventual x ↔ t < n ∨ ∀ h, t < h → S h := by\n  classical\n  have hg : ∀ h, gate n x d h ↔ ∀ g, g < h → n ≤ g → x g ∧ g ≠ t := by\n    intro h\n    constructor\n    · intro H g gh gn\n      rcases H g gh with hn | ⟨hx, hd⟩\n      · omega\n      · exact ⟨hx, (first_hole d t pre hole g).1 hd⟩\n    · intro H g gh\n      by_cases gn : g < n\n      · exact Or.inl gn\n      · have hh := H g gh (by omega)\n        exact Or.inr ⟨hh.1, (first_hole d t pre hole g).2 hh.2⟩\n  constructor\n  · intro ⟨H, hH⟩\n    by_cases tn : t < n\n    · exact Or.inl tn\n    · right\n      intro h th\n      apply Classical.byContradiction\n      intro sh\n      have nx : ¬ x h := by\n        intro xh\n        rcases (eqn h).1 xh with ⟨hs, _⟩ | ⟨_, hw⟩\n        · exact sh hs\n        · exact ((hg h).1 hw t th (by omega)).2 rfl\n      let z := H + h + n + k + 1\n      rcases (eqn z).1 (hH z (by dsimp [z]; omega)) with ⟨_, hf⟩ | ⟨_, hw⟩\n      · exact nx (hf h (by dsimp [z]; omega))\n      · exact nx ((hg z).1 hw h (by dsimp [z]; omega) (by omega)).1\n  · intro good\n    have allx : ∀ h, x h := by\n      intro h\n      induction h using Nat.strongRecOn with\n      | ind h ih =>\n        apply (eqn h).2\n        by_cases sh : S h\n        · exact Or.inl ⟨sh, fun g gh => ih g (by omega)⟩\n        · apply Or.inr\n          refine ⟨sh, (hg h).2 ?_⟩\n          intro g gh gn\n          refine ⟨ih g gh, ?_⟩\n          intro e\n          subst g\n          rcases good with tn | tail\n          · omega\n          · exact sh (tail h gh)\n    exact ⟨0, fun h _ => allx h⟩\n#print axioms graded_self_law\n\ntheorem dbtrace_semantics (n k : Nat) (S : Nat → Prop) (h : Nat) :\n    blend S (fun h => ∀ g, g + k ≤ h → False)\n      (gate n (fun _ => False) (fun _ => False)) h ↔ dbtrace n k S h := by\n  have hf : (∀ g, g + k ≤ h → False) ↔ h < k := by\n    constructor\n    · intro H; by_cases e : h < k; exact e; exact False.elim (H 0 (by omega))\n    · intro e g hg; omega\n  have hw : gate n (fun _ => False) (fun _ => False) h ↔ h ≤ n := by\n    constructor\n    · intro H\n      by_cases hh : h ≤ n\n      · exact hh\n      · rcases H n (by omega) with hn | hf\n        · omega\n        · exact False.elim hf.1\n    · intro H g gh; exact Or.inl (by omega)\n  unfold blend dbtrace\n  dsimp only\n  rw [hf, hw]\n\ntheorem trace_first_exists (n k : Nat) (S : Nat → Prop) :\n    ∃ t, t ≤ n+k+1 ∧ ¬ dbtrace n k S t ∧ ∀ j, j < t → dbtrace n k S j := by\n  apply least_failure (dbtrace n k S) (n+k+1)\n  intro H\n  rcases H with ⟨_, H⟩ | ⟨_, H⟩ <;> omega\n\ntheorem early_iff (n k t : Nat) (S : Nat → Prop)\n    (pre : ∀ j, j < t → dbtrace n k S j) (hole : ¬ dbtrace n k S t) :\n    t < n ↔ ∃ j, k ≤ j ∧ j < n ∧ S j := by\n  classical\n  constructor\n  · intro tn\n    have st : S t := Classical.byContradiction (fun ns => hole (Or.inr ⟨ns, by omega⟩))\n    have kt : k ≤ t := by\n      by_cases tk : t < k\n      · exact False.elim (hole (Or.inl ⟨st, tk⟩))\n      · omega\n    exact ⟨t, kt, tn, st⟩\n  · intro ⟨j, jk, jn, sj⟩\n    by_cases jt : j < t\n    · rcases pre j jt with ⟨_, e⟩ | ⟨ns, _⟩\n      · omega\n      · exact False.elim (ns sj)\n    · omega\n#print axioms dbtrace_semantics\n#print axioms trace_first_exists\n#print axioms early_iff\n\ntheorem fb_partner (n k : Nat) (hk : 1 ≤ k) (hn : 2 ≤ n) (S x y : Nat → Prop)\n    (ex : ∀ h, x h ↔ blend S (fun h => ∀ g, g + k ≤ h → y g)\n       (gate n y (fun g => g = 0)) h)\n    (ey : ∀ h, y h ↔ ∀ g, g < h → x g) :\n    ∀ h, x h ∧ y h := by\n  classical\n  intro h\n  induction h using Nat.strongRecOn with\n  | ind h ih =>\n    constructor\n    · apply (ex h).2\n      by_cases sh : S h\n      · exact Or.inl ⟨sh, fun g gh => (ih g (by omega)).2⟩\n      · refine Or.inr ⟨sh, ?_⟩\n        intro g gh\n        by_cases gn : g < n\n        · exact Or.inl gn\n        · exact Or.inr ⟨(ih g gh).2, Or.inr (fun H => by have := H 1 (by omega); omega)⟩\n    · exact (ey h).2 (fun g gh => (ih g gh).1)\n\ntheorem cb_partner (n k : Nat) (S : Nat → Prop) :\n    ∀ h, blend S (fun h => ∀ g, g + k ≤ h → True)\n      (gate n (fun _ => True) (fun _ => True)) h := by\n  classical\n  intro h\n  by_cases sh : S h\n  · exact Or.inl ⟨sh, fun _ _ => trivial⟩\n  · exact Or.inr ⟨sh, fun _ _ => Or.inr ⟨trivial, Or.inl trivial⟩⟩\n\n#print axioms fb_partner\n#print axioms cb_partner\n'
assert hashlib.sha256(LEAN.encode()).hexdigest() == 'fb6ee912f23976ec5f09280bc85212abf2023195dfd5122f5fb6de7fec32d161'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=90)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 6
for old,new in [('t < n ∨ ∀ h, t < h → S h','t ≤ n ∨ ∀ h, t < h → S h'),('(hk : 1 ≤ k)','(hk : 0 ≤ k)'),('k ≤ j ∧ j < n ∧ S j','k ≤ j ∧ j ≤ n ∧ S j')]:
    bad=LEAN.replace(old,new)
    assert bad != LEAN
    r=subprocess.run([binary,'--stdin'],input=bad,text=True,capture_output=True,timeout=15)
    assert r.returncode != 0, 'negative control accepted'
print('PASS: six general Lean theorems; three mutations rejected')
